import apiClient from './client'

export interface LicenseRead {
  license_id: string
  edition: string
  max_nodes: number
  issued_at: string | null
  expires_at: string | null
  server_install_id: string | null
  is_valid: boolean
  error_message: string | null
}

export interface LicenseFeatures {
  edition: string
  features: Record<string, boolean | number | string>
}

export interface UploadLicenseResponse {
  success: boolean
  message: string
  license: LicenseRead
}

export async function getLicense(): Promise<LicenseRead> {
  const response = await apiClient.get<LicenseRead>('/v1/license')
  return response.data
}

export async function getLicenseFeatures(): Promise<LicenseFeatures> {
  const response = await apiClient.get<LicenseFeatures>('/v1/license/features')
  return response.data
}

export async function uploadLicense(file: File): Promise<UploadLicenseResponse> {
  const formData = new FormData()
  formData.append('file', file)
  const response = await apiClient.post<UploadLicenseResponse>(
    '/v1/license/upload',
    formData,
    {
      headers: {
        'Content-Type': 'multipart/form-data',
      },
    }
  )
  return response.data
}
